import json, random, subprocess, sys, math
sys.path.insert(0, '/workspace/tmp')
sys.path.insert(0, '/workspace/submission')
import ref

def gen(seed):
    rnd = random.Random(seed)
    nn = rnd.randint(2, 8)
    nodes = rnd.sample(range(1, 200), nn)
    ixps = [n for n in nodes if rnd.random() < 0.25]
    if len(ixps) > 3:
        ixps = ixps[:3]
    rib = []
    for _ in range(rnd.randint(0, 10)):
        ln = rnd.randint(0, min(6, nn))
        base = rnd.sample(nodes, ln) if ln else []
        raw = []
        for x in base:
            raw.append(x)
            if rnd.random() < 0.2:
                raw.append(x)
        if rnd.random() < 0.15 and ixps:
            pos = rnd.randint(0, len(raw))
            raw = raw[:pos] + [rnd.choice(ixps)] + raw[pos:]
        if not raw:
            continue
        rib.append({'path': raw, 'count': rnd.randint(1, 5)})
    # normalize + peel with reference to compute core links and order
    ixset = set(ixps)
    agg = {}
    for rec in rib:
        p = ref.normalize(rec['path'], ixset)
        if len(p) < 2 or len(set(p)) != len(p):
            continue
        agg[tuple(p)] = agg.get(tuple(p), 0) + rec['count']
    final, rounds = ref.ref_peel(agg)
    core = set()
    for p in final:
        for i in range(len(p) - 1):
            core.add(ref.canon(p[i], p[i + 1]))
    if len(core) > 8:
        return None
    occs = ref.ref_occurrences(final)
    adj = ref.scope_graph(occs, core)
    order = ref.find_order(adj)
    if order is None:
        return None
    order = [[u, v] for (u, v) in order]
    # priors on random links (some reversed, some not in rib)
    pool = set(core) | set(rounds)
    extra = [(rnd.randint(200, 400), rnd.randint(200, 400)) for _ in range(2)]
    pool |= {ref.canon(a, b) for a, b in extra if a != b}
    priors = []
    used = set()
    for _ in range(rnd.randint(0, 5)):
        if not pool:
            break
        l = rnd.choice(sorted(pool))
        if l in used:
            continue
        used.add(l)
        w = [rnd.randint(0, 5) for _ in range(3)]
        if sum(w) == 0:
            w[rnd.randint(0, 2)] = 1
        pair = list(l) if rnd.random() < 0.5 else [l[1], l[0]]
        priors.append({'link': pair, 'weights': w})
    declared = []
    used = set()
    for _ in range(rnd.randint(0, 4)):
        if not pool:
            break
        l = rnd.choice(sorted(pool))
        if l in used:
            continue
        used.add(l)
        pair = list(l) if rnd.random() < 0.5 else [l[1], l[0]]
        declared.append({'link': pair, 'rel': rnd.choice(['c2p', 'p2p', 'p2c'])})
    queries = []
    for i in range(rnd.randint(0, 6)):
        ln = rnd.randint(0, min(6, nn + 2))
        base = [rnd.choice(nodes) for _ in range(ln)]
        raw = []
        for x in base:
            raw.append(x)
            if rnd.random() < 0.2:
                raw.append(x)
        if rnd.random() < 0.1 and ixps:
            pos = rnd.randint(0, len(raw))
            raw = raw[:pos] + [rnd.choice(ixps)] + raw[pos:]
        th = sorted([rnd.randint(0, 4), rnd.randint(1, 4)])
        queries.append({'id': 'q%d_%d' % (seed, i), 'path': raw,
                        'threshold': th})
    return {'version': 1, 'ixps': ixps, 'rib': rib, 'priors': priors,
            'declared': declared, 'order': order, 'queries': queries}


def equal(a, b):
    if type(a) is dict:
        return type(b) is dict and a.keys() == b.keys() and all(
            equal(a[k], b[k]) for k in a)
    if type(a) is list:
        return type(b) is list and len(a) == len(b) and all(
            equal(x, y) for x, y in zip(a, b))
    if type(a) is float:
        return type(b) in (int, float) and math.isfinite(b) and abs(a - b) <= 1e-9
    return type(a) is type(b) and a == b


def main():
    lo, hi = int(sys.argv[1]), int(sys.argv[2])
    fails = 0
    tested = 0
    zero_part = 0
    for seed in range(lo, hi):
        doc = gen(seed)
        if doc is None:
            continue
        expected = ref.ref_solve(doc)
        if expected.get('error') == 'zero-partition':
            zero_part += 1
        raw = json.dumps(doc).encode()
        got = subprocess.run([sys.executable, '-I',
                              '/workspace/submission/main.py'],
                             input=raw, capture_output=True, cwd='/workspace')
        try:
            actual = json.loads(got.stdout.decode())
        except Exception:
            print('seed', seed, 'BAD OUTPUT', got.stdout[:300], got.stderr[:500])
            fails += 1
            continue
        if got.returncode != 0 or not equal(expected, actual):
            fails += 1
            print('seed', seed, 'MISMATCH')
            print(' input:', json.dumps(doc))
            print(' expected:', json.dumps(expected))
            print(' actual  :', json.dumps(actual))
            if fails > 3:
                break
        tested += 1
    print('tested', tested, 'fails', fails, 'zero-partition cases', zero_part)
    return fails


if __name__ == '__main__':
    sys.exit(1 if main() else 0)
